mapper.sql:
WHERE missed_on >= #{fromDate} AND missed_on <= #{toDate}

    AND route_no = #{routeNo}


    AND reason = #{reason}

mapper.select:
SELECT k.word AS label,
       COUNT(m.id) AS trip_count,
       COALESCE(SUM(m.missed_count), 0) AS missed_sum
FROM (VALUES

    (#{word})

) AS k(word)
LEFT JOIN hd_missed_trip m
       ON position(lower(k.word) in lower(coalesce(m.note, ''))) > 0
      AND m.missed_on >= #{fromDate} AND m.missed_on <= #{toDate}

      AND m.route_no = #{routeNo}


      AND m.reason = #{reason}

GROUP BY k.word
ORDER BY missed_sum DESC, k.word
